SELECT School, EILName
FROM schools
WHERE CDSCode = '1612590136051';

SELECT ROUND(
  100.0 * COUNT(*) FILTER (
    WHERE NOT EXISTS (
      SELECT 1
      FROM member m
      WHERE m.link_to_major = major.major_id
    )
  ) / NULLIF(COUNT(*), 0),
  2
) AS percentage_majors_with_no_club_members
FROM major;

SELECT COUNT(DISTINCT ID) AS patient_count
FROM Patient
WHERE Diagnosis LIKE '%psoriatic arthritis%';
